query_string:
{% set style = config['prod_lower_level'] %}
{% set store_code = config['loc_lower_level'] %}

 With 
   ThisYear AS (
    SELECT 
    count(distinct {{style}}) as Available_Offers_SKU_TY
    FROM {sales_table}
    WHERE week_id >= {timeline_start_week_id}
    AND week_id <= {timeline_end_week_id}
    {filter_condition}
    and discount_flag = "Discount"
    ),

    LastYear AS (
    SELECT 
    count(distinct {{style}}) as Available_Offers_SKU_LY
    FROM {sales_table}
    WHERE week_id >= {compare_start_week_id}
    AND week_id <= {compare_end_week_id}
    {filter_condition}
    and discount_flag = "Discount"
    )

    Select 
       Available_Offers_SKU_TY,
       Available_Offers_SKU_LY,
       ((Available_Offers_SKU_TY - Available_Offers_SKU_LY)/Available_Offers_SKU_LY)*100 AS Available_Offers_SKU_PCT_Variance
    FROM ThisYear
    CROSS JOIN LastYear

select 
{hierachy_list}
SUBSTR(CAST(week_id AS STRING), 1, 4) AS fiscal_year,
sum(total_visits) as footfalls
from {store_labour_and_hours}
where ((week_id >= {timeline_start_week_id} and week_id <= {timeline_end_week_id}) or 
(week_id >= {compare_start_week_id} and week_id <= {compare_end_week_id}))
{filter_condition}
group by {hierachy_list} fiscal_year

with this_year_sales as (
 select 
 {hierachy_list}
 channel,
 round(sum(sales),2) as total_sales_TY
 from {sales_table}
 where week_id >= {timeline_start_week_id} and week_id <= {timeline_end_week_id}
 {filter_condition}
 group by {hierachy_list} channel
 ),

 last_year_sales as (
 select 
 {hierachy_list}
 channel,
 round(sum(sales),2) as total_sales_LY
 from {sales_table}
 where week_id >= {compare_start_week_id} and week_id <= {compare_end_week_id}
 {filter_condition}
 group by {hierachy_list} channel
 )

 select 
 {hierachy_list}
 channel,
 total_sales_TY,
 total_sales_LY,
 round(((total_sales_TY - total_sales_LY) / total_sales_LY) * 100,2) AS variance_sales
 from this_year_sales 
 full outer join last_year_sales 
 using({hierachy_list} channel)

{% set style = config['prod_lower_level'] %}
{% set store_code = config['loc_lower_level'] %}
{% set top_products_cte %}
with sales_data as (
   select
       fiscal_year,
       week_id,
       {{ style }} as style,
       sum(sales) as total_sales
   from {sales_table}
   where ((week_id >= {timeline_start_week_id} and week_id <= {timeline_end_week_id}) or
          (week_id >= {compare_start_week_id} and week_id <= {compare_end_week_id}))
   {filter_condition}
   group by fiscal_year, week_id, {{ style }}
),
ranked_sales as (
   select
       fiscal_year,
       week_id,
       {{ style }} as style,
       total_sales,
       sum(total_sales) over (partition by fiscal_year, week_id order by total_sales desc
                              rows between unbounded preceding and current row) as cumulative_sales,
       sum(total_sales) over (partition by fiscal_year, week_id) as total_revenue,
       row_number() over (partition by fiscal_year, week_id order by total_sales desc) as sales_rank
   from sales_data
),
top_products as (
   select
       fiscal_year,
       week_id,
       {{ style }} as style
   from ranked_sales
   where (cumulative_sales / total_revenue) <= 0.8
   or sales_rank <= 50
)
{% endset %}
{{ top_products_cte }}
{% set hierarchy_columns = hierarchy_list if hierarchy_list else [] %}
, inventory_data_timeline as (
   select
       i.fiscal_year,
       i.week_id,
       i.{{ store_code }} as store_code,
       i.{{ style }} as style
       {% for column in hierarchy_columns %}
       , i.{{ column }} as timeline_{{ column }}
       {% endfor %}
       , coalesce(ROUND(AVG(i.eoh), 2), 0) as available_inventory
   from {inventory_table} i
   inner join top_products tp
       on i.fiscal_year = tp.fiscal_year
       and i.week_id = tp.week_id
       and i.{{ style }} = tp.style
   where (i.week_id >= {timeline_start_week_id} and i.week_id <= {timeline_end_week_id})
   {filter_condition_with_alias}
   group by i.fiscal_year, i.week_id, i.{{ store_code }}, i.{{ style }}
   {% for column in hierarchy_columns %}
   , i.{{ column }}
   {% endfor %}
),
inventory_data_comparable as (
   select
       i.fiscal_year,
       i.week_id,
       i.{{ store_code }} as store_code,
       i.{{ style }} as style
       {% for column in hierarchy_columns %}
       , i.{{ column }} as comparable_{{ column }}
       {% endfor %}
       , coalesce(ROUND(AVG(i.eoh), 2), 0) as available_inventory
   from {inventory_table} i
   inner join top_products tp
       on i.fiscal_year = tp.fiscal_year
       and i.week_id = tp.week_id
       and i.{{ style }} = tp.style
   where (i.week_id >= {compare_start_week_id} and i.week_id <= {compare_end_week_id})
   {filter_condition_with_alias}
   group by i.fiscal_year, i.week_id, i.{{ store_code }}, i.{{ style }}
   {% for column in hierarchy_columns %}
   , i.{{ column }}
   {% endfor %}
)
{% if config['loc_lower_level'] in loc_level and config['prod_lower_level'] in prod_level %}
   , weekly_stockout_data_timeline as (
       select
           fiscal_year,
           week_id,
           {{ store_code }} as store_code,
           {{ style }} as style
           {% for column in hierarchy_columns %}
           , timeline_{{ column }}
           {% endfor %}
           , case when available_inventory = 0 then 1 else 0 end as is_stockout
       from inventory_data_timeline
   ),
   weekly_stockout_data_comparable as (
       select
           fiscal_year,
           week_id,
           {{ store_code }} as store_code,
           {{ style }} as style
           {% for column in hierarchy_columns %}
           , comparable_{{ column }}
           {% endfor %}
           , case when available_inventory = 0 then 1 else 0 end as is_stockout
       from inventory_data_comparable
   )
   , sum_stockout_timeline_cte as (
       select
           {{ store_code }} as store_code,
           {{ style }} as style
           {% for column in hierarchy_columns %}
           , timeline_{{ column }}
           {% endfor %}
           , sum(is_stockout) as total_stockout_timeline
       from weekly_stockout_data_timeline
       group by {{ store_code }}, {{ style }}
       {% for column in hierarchy_columns %}
       , timeline_{{ column }}
       {% endfor %}
   ),
   sum_stockout_comparable_cte as (
       select
           {{ store_code }} as store_code,
           {{ style }} as style
           {% for column in hierarchy_columns %}
           , comparable_{{ column }}
           {% endfor %}
           , sum(is_stockout) as total_stockout_comparable
       from weekly_stockout_data_comparable
       group by {{ store_code }}, {{ style }}
       {% for column in hierarchy_columns %}
       , comparable_{{ column }}
       {% endfor %}
   )
   select
       t.store_code,
       t.style
       {% for column in hierarchy_columns %}
       , t.timeline_{{ column }} as {{ column }}
       {% endfor %}
       , t.total_stockout_timeline,
       c.total_stockout_comparable
   from sum_stockout_timeline_cte t
   join sum_stockout_comparable_cte c
   on t.store_code = c.store_code 
   and t.style = c.style
   {% for column in hierarchy_columns %}
   and t.timeline_{{ column }} = c.comparable_{{ column }}
   {% endfor %}
   order by t.store_code, t.style
{% else %}
    , weekly_stockout_data_timeline as (
        select
            fiscal_year,
            week_id
            {% for column in hierarchy_columns %}
            , timeline_{{ column }}
            {% endfor %}
            {% if store_code in loc_level %}
            , {{ store_code }} as store_code
            {% endif %}
            {% if style in prod_level %}
            , {{ style }} as style
            {% endif %}
            , count(distinct concat({{ store_code }}, '_', {{ style }})) as total_store_product_combos,
            count(distinct (case when available_inventory = 0 then concat({{ store_code }}, '_', {{ style }}) end)) as stockout_store_product_combos
        from inventory_data_timeline
        group by fiscal_year, week_id
        {% for column in hierarchy_columns %}
        , timeline_{{ column }}
        {% endfor %}
        {% if store_code in loc_level %}
        , {{ store_code }}
        {% endif %}
        {% if style in prod_level %}
        , {{ style }}
        {% endif %}
    ),
    weekly_stockout_data_comparable as (
        select
            fiscal_year,
            week_id
            {% for column in hierarchy_columns %}
            , comparable_{{ column }}
            {% endfor %}
            {% if store_code in loc_level %}
            , {{ store_code }} as store_code
            {% endif %}
            {% if style in prod_level %}
            , {{ style }} as style
            {% endif %}
            , count(distinct concat({{ store_code }}, '_', {{ style }})) as total_store_product_combos,
            count(distinct (case when available_inventory = 0 then concat({{ store_code }}, '_', {{ style }}) end)) as stockout_store_product_combos
        from inventory_data_comparable
        group by fiscal_year, week_id
        {% for column in hierarchy_columns %}
        , comparable_{{ column }}
        {% endfor %}
        {% if store_code in loc_level %}
        , {{ store_code }}
        {% endif %}
        {% if style in prod_level %}
        , {{ style }}
        {% endif %}
    )
    select
        {% if hierarchy_columns %}
        {% for column in hierarchy_columns %}
        t.timeline_{{ column }} as {{ column }}{% if not loop.last %}, {% endif %}
        {% endfor %}
        {% endif %}
        {% if store_code in loc_level %}
        {% if hierarchy_columns %}, {% endif %}
        t.store_code
        {% endif %}
        {% if style in prod_level %}
        {% if hierarchy_columns or store_code in loc_level %}, {% endif %}
        t.style
        {% endif %}
        {% if not (hierarchy_columns or store_code in loc_level or style in prod_level) %}
        'Overall' as overall
        {% endif %}
        , 100 - round(avg(100.0 * t.stockout_store_product_combos / t.total_store_product_combos), 2) as availability_percentage_ty,
        100 - round(avg(100.0 * c.stockout_store_product_combos / c.total_store_product_combos), 2) as availability_percentage_ly
    from weekly_stockout_data_timeline t
    left join weekly_stockout_data_comparable c
    on 1=1
    {% for column in hierarchy_columns %}
    and t.timeline_{{ column }} = c.comparable_{{ column }}
    {% endfor %}
    {% if store_code in loc_level %}
    and t.store_code = c.store_code
    {% endif %}
    {% if style in prod_level %}
    and t.style = c.style
    {% endif %}
    {% if hierarchy_columns or store_code in loc_level or style in prod_level %}
    group by
    {% for column in hierarchy_columns %}
    t.timeline_{{ column }}{% if not loop.last or store_code in loc_level or style in prod_level %}, {% endif %}
    {% endfor %}
    {% if store_code in loc_level %}
    t.store_code{% if style in prod_level %}, {% endif %}
    {% endif %}
    {% if style in prod_level %}
    t.style
    {% endif %}
    order by
    {% for column in hierarchy_columns %}
    t.timeline_{{ column }}{% if not loop.last or store_code in loc_level or style in prod_level %}, {% endif %}
    {% endfor %}
    {% if store_code in loc_level %}
    t.store_code{% if style in prod_level %}, {% endif %}
    {% endif %}
    {% if style in prod_level %}
    t.style
    {% endif %}
    {% endif %}
{% endif %}

{% set style = config['prod_lower_level'] %}
{% set store_code = config['loc_lower_level'] %}
{% set diff_kpi_name = 'return_LY_Variance' %}


with current_period_data as (
    select
        week_id,
        {{store_code}} as store_code,
        {{style}} as style,
        sum(quantity) as quantity,
        sum(return_quantity) as return_quantity,
        sum(ABS(return_quantity)) /NULLIF(sum(quantity), 0) as return_percentage
    from {sales_subset_causal}
    where week_id >= {timeline_start_week_id} and week_id <= {timeline_end_week_id}
    {filter_condition}
    group by week_id, store_code, style
),
current_total_quantity as (
    select sum(quantity) as total_qty
    from current_period_data
),
current_weighted_return as (
    select sum(return_percentage * (quantity / total_qty)) as weighted_return
    from current_period_data, current_total_quantity
),

comparable_period_data as (
    select
        week_id,
        {{store_code}} as store_code,
        {{style}} as style,
        sum(quantity) as quantity,
        sum(return_quantity) as return_quantity,
        sum(ABS(return_quantity)) /NULLIF(sum(quantity), 0) as return_percentage
    from {sales_subset_causal}
    where week_id >= {compare_start_week_id} and week_id <= {compare_end_week_id}
    {filter_condition}
    group by week_id, store_code, style
),
comparable_total_quantity as (
    select sum(quantity) as total_qty
    from comparable_period_data
),
comparable_weighted_return as (
    select sum(return_percentage * (quantity / total_qty)) as weighted_return
    from comparable_period_data, comparable_total_quantity
)

select
    current_weighted_return.weighted_return * 100 as return_TY,
    comparable_weighted_return.weighted_return * 100 as return_LY,
    (current_weighted_return.weighted_return - comparable_weighted_return.weighted_return) * 100 as {{diff_kpi_name}}
from current_weighted_return, comparable_weighted_return

